"""
Sliding-window rate limiter for POST /api/chat/* endpoints.
"""
import collections
import math
import os
import threading
import time
from typing import Callable

from fastapi import Request
from fastapi.responses import JSONResponse
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.types import ASGIApp


def _client_ip(request: Request) -> str:
    forwarded = request.headers.get("X-Forwarded-For", "")
    if forwarded:
        return forwarded.split(",")[0].strip()
    if request.client:
        return request.client.host
    return "unknown"


class SlidingWindowRateLimiter:
    _WINDOW_SECONDS = 60.0

    def __init__(self, clock: Callable[[], float] | None = None) -> None:
        self._windows: dict[str, collections.deque] = {}
        self._lock = threading.Lock()
        self._clock: Callable[[], float] = clock if clock is not None else time.time

    def _limit(self) -> int:
        return int(os.getenv("RATE_LIMIT_RPM", "10"))

    def check(self, key: str) -> tuple[bool, int]:
        now = self._clock()
        limit = self._limit()
        window = self._WINDOW_SECONDS

        with self._lock:
            dq = self._windows.setdefault(key, collections.deque())
            cutoff = now - window
            while dq and dq[0] <= cutoff:
                dq.popleft()
            if len(dq) >= limit:
                retry_after = max(1, math.ceil(dq[0] + window - now))
                return False, retry_after
            dq.append(now)
            return True, 0


class ChatRateLimitMiddleware(BaseHTTPMiddleware):
    def __init__(self, app: ASGIApp, limiter: SlidingWindowRateLimiter) -> None:
        super().__init__(app)
        self._limiter = limiter

    async def dispatch(self, request: Request, call_next):
        if request.method == "POST" and request.url.path.startswith("/api/chat/"):
            ip = _client_ip(request)
            allowed, retry_after = self._limiter.check(ip)
            if not allowed:
                return JSONResponse(
                    status_code=429,
                    content={"error": "rate_limit_exceeded", "retry_after": retry_after},
                )
        return await call_next(request)
